code.cpp:
class Solution {
public:
    int countTriples(int n) {
        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int s = a * a + b * b;
                int c = (int)round(sqrt((double)s));
                if (c >= 1 && c <= n && c * c == s) {
                    count++;
                }
            }
        }
        return count;
    }
};
